import {chromium} from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
const b=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader']});
const p=await b.newPage({viewport:{width:1280,height:720}});
await p.route('**/game.js',async route=>{
 const r=await route.fetch(); let body=await r.text();
 body += `\nwindow.__debug=()=>({yaw,pitch,camera:[camera.position.x,camera.position.y,camera.position.z],enemies:enemies.filter(e=>e.parent).map(e=>[e.position.x,e.position.y,e.position.z]),hits:(()=>{camera.updateMatrixWorld();raycaster.setFromCamera(new THREE.Vector2(0,0),camera);return raycaster.intersectObjects(enemies.filter(e=>e.parent).flatMap(e=>e.children.filter(c=>c.isMesh)),false).slice(0,5).map(h=>({name:h.object.name,dist:h.distance,point:h.point.toArray(),enemy:enemies.findIndex(e=>e===h.object.parent)}))})()});window.__set=(y,p)=>{yaw=y;pitch=p;camera.rotation.set(pitch,yaw,0,'YXZ')};window.__fire=fire;`;
 await route.fulfill({...r,body,headers:{...r.headers(),'content-type':'text/javascript'}})
});
await p.goto('http://localhost:3000'); await p.locator('#start-button').click(); await p.waitForTimeout(300);
for(const [y,pt] of [[.22,0],[.22,.04],[.22,-.04],[-.22,0]]) { await p.evaluate(([y,pt])=>window.__set(y,pt),[y,pt]); console.log(y,pt,await p.evaluate(()=>window.__debug())); }
await p.evaluate(()=>{window.__set(.22,0);window.__fire()}); await p.waitForTimeout(300);
console.log('after fire',await p.locator('#ammo-value').innerText());
await p.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:65}); await b.close();

